#!/usr/bin/env bash
# Positive control for count_lint_issues.py and for the plain <issue> count used in the
# three-way cross-check (dispatch 2026-10-12-01). control-expected.json was written by hand from
# the counts stated in control-report.xml's header, not generated by the script.
#
# Three checks, each of which must come out as stated:
#   1. the counter's JSON on the control equals control-expected.json        -> must MATCH
#   2. the plain count of <issue> elements on the control is 5               -> must be 5
#   3. the same comparison on a copy with one Warning changed to Error       -> must DIFFER
# Check 3 is what shows check 1 can fail: a comparison only ever seen matching is not evidence.
set -euo pipefail
here="$(cd "$(dirname "$0")" && pwd)"
counter="$here/count_lint_issues.py"
control="$here/control-report.xml"
expected="$here/control-expected.json"
root="/runner/work/Forager/Forager"
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

compare() {  # compare <json-a> <json-b>: exit 0 if equal as parsed JSON
  python3 - "$1" "$2" <<'PY'
import json, sys
a, b = (json.load(open(p)) for p in sys.argv[1:3])
if a != b:
    for key in sorted(set(a) | set(b)):
        if a.get(key) != b.get(key):
            print("    differs at {}: got {} expected {}".format(key, a.get(key), b.get(key)))
    sys.exit(1)
PY
}

plain_count() {  # the same command the report uses on lint's real XML
  grep -oE '<issue([[:space:]]|>|$)' "$1" | wc -l | tr -d ' '
}

status=0

python3 "$counter" "$control" --root "$root" --json > "$tmp/actual.json"
if compare "$tmp/actual.json" "$expected"; then
  echo "check 1 PASS: counter output equals the hand-written expected counts"
else
  echo "check 1 FAIL: counter output differs from the hand-written expected counts"; status=1
fi

n="$(plain_count "$control")"
if [ "$n" = 5 ]; then
  echo "check 2 PASS: plain <issue> count is 5"
else
  echo "check 2 FAIL: plain <issue> count is $n, expected 5"; status=1
fi

# Mutate exactly one severity: the ControlWarnB issue's Warning becomes Error.
python3 - "$control" "$tmp/mutated.xml" <<'PY'
import sys
src, dst = sys.argv[1:3]
text = open(src).read()
old = 'id="ControlWarnB"\n        severity="Warning"'
assert text.count(old) == 1, "mutation anchor not found exactly once"
open(dst, "w").write(text.replace(old, 'id="ControlWarnB"\n        severity="Error"'))
PY
python3 "$counter" "$tmp/mutated.xml" --root "$root" --json > "$tmp/mutated.json"
if compare "$tmp/mutated.json" "$expected"; then
  echo "check 3 FAIL: a one-severity mutation still matched; the comparison cannot fail"; status=1
else
  echo "check 3 PASS: the one-severity mutation was detected (differences listed above)"
fi

echo
echo "Counter tables on the control:"
python3 "$counter" "$control" --root "$root"
exit "$status"
